static void sine_control_set_profile_callback(sine_control_state_t *state,
                                               float frequency_hz,
                                               float amplitude,
                                               int cmock_num_calls)
{
    (void)state;
    (void)cmock_num_calls;

    if (profile_calls >= 500 && profile_calls < 1500) {
        if (frequency_hz != APP_MOTOR_RUN_FREQUENCY_HZ ||
            amplitude > APP_MOTOR_RUN_AMPLITUDE) {
            hold_profile_violations++;
        }
    }

    if (profile_calls == 500) {
        profile_frequency_at_first_hold = frequency_hz;
        profile_amplitude_at_first_hold = amplitude;
    } else if (profile_calls == 1499) {
        profile_frequency_at_last_hold = frequency_hz;
        profile_amplitude_at_last_hold = amplitude;
    } else if (profile_calls == 1500) {
        profile_frequency_at_shutdown_start = frequency_hz;
        profile_amplitude_at_shutdown_start = amplitude;
    }

    profile_calls++;
}

static x_nucleo_ihm16m1_status_t motor_platform_drive_callback(float duty_u,
                                                                 float duty_v,
                                                                 float duty_w,
                                                                 int cmock_num_calls)
{
    (void)duty_v;
    (void)duty_w;
    (void)cmock_num_calls;

    if (drive_calls >= 500 && drive_calls < 1500 &&
        duty_u > APP_MOTOR_RUN_AMPLITUDE) {
        hold_drive_violations++;
    }

    drive_calls++;
    return X_NUCLEO_IHM16M1_OK;
}

