void test_PERF_006_01(void)
{
    motor_sequence_t sequence;

    motor_sequence_init(&sequence);
    for (unsigned int i = 0U; i < 800U; ++i) {
        motor_sequence_step(&sequence, APP_MOTOR_CONTROL_PERIOD_MS);
    }
    TEST_ASSERT_EQUAL_INT(MOTOR_SEQUENCE_HOLD, sequence.state);
    TEST_ASSERT_EQUAL_INT(8000, sequence.elapsed_ms);

    for (unsigned int i = 0U; i < 999U; ++i) {
        motor_sequence_step(&sequence, APP_MOTOR_CONTROL_PERIOD_MS);
    }
    TEST_ASSERT_EQUAL_INT(MOTOR_SEQUENCE_HOLD, sequence.state);
    TEST_ASSERT_EQUAL_INT(17990, sequence.elapsed_ms);

    motor_sequence_step(&sequence, APP_MOTOR_CONTROL_PERIOD_MS);
    TEST_ASSERT_EQUAL_INT(MOTOR_SEQUENCE_SHUTDOWN_RAMP, sequence.state);
    TEST_ASSERT_EQUAL_INT(18000, sequence.elapsed_ms);

    app_start();

    TEST_ASSERT_EQUAL_INT(1700, profile_calls);
    TEST_ASSERT_EQUAL_INT(1000, 1500 - 500);
    TEST_ASSERT_EQUAL_INT(0, hold_profile_violations);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, APP_MOTOR_RUN_FREQUENCY_HZ,
                             profile_frequency_at_first_hold);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, APP_MOTOR_RUN_AMPLITUDE,
                             profile_amplitude_at_first_hold);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, APP_MOTOR_RUN_FREQUENCY_HZ,
                             profile_frequency_at_last_hold);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, APP_MOTOR_RUN_AMPLITUDE,
                             profile_amplitude_at_last_hold);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, APP_MOTOR_RUN_FREQUENCY_HZ,
                             profile_frequency_at_shutdown_start);
    TEST_ASSERT_FLOAT_WITHIN(0.001F, APP_MOTOR_RUN_AMPLITUDE,
                             profile_amplitude_at_shutdown_start);
    TEST_ASSERT_EQUAL_INT(0, hold_drive_violations);
}
